const PAR_IMAGE = new Map<unknown, CadrageBuste>(MESURES);

export function cadrageBuste(source: ImageSourcePropType | null | undefined): CadrageBuste {
  return (source != null && PAR_IMAGE.get(source as unknown)) || CADRAGE_DEFAUT;
}

/** Style de l'image dans le rond (pourcentages du rond, quel que soit son diametre) */
export function styleBuste(source: ImageSourcePropType | null | undefined) {
  const c = cadrageBuste(source);
  const pc = (v: number) => `${Math.round(v * 10000) / 100}%` as const;
  return { position: 'absolute' as const, width: pc(c.w), height: pc(c.h), left: pc(c.l), top: pc(c.t) };
}
